INSERT INTO mei.bid_sections (section_id, bid_id, section_key, section_name, status, compiled_data, approved_data, source_module, input_version, confidence_score, flag_count, flags, approved_by, approved_at, correction_note, created_at, updated_at) VALUES ('74928b3f-abe7-4f14-b940-7e30add75b01'::uuid, '2332d258-c7cd-42cc-9d2c-60eb3af292e6'::uuid, 'acceptance', 'Acceptance Criteria', 'pending', '{"criteria": [{"id": "AC-01", "description": "Compiled clinical data flows match the documented data dictionary with zero unmapped fields.", "measurement": "Schema diff report", "responsible": "Data Lead", "verification": "Automated test in CI"}, {"id": "AC-02", "description": "End-to-end pipeline latency for in-scope feeds is less than 90 minutes from source landing.", "measurement": "Synthetic latency probe", "responsible": "Platform Eng", "verification": "Production monitoring 7-day rolling avg"}, {"id": "AC-03", "description": "Trained models meet or exceed the agreed AUC threshold of 0.82 on the held-out test set.", "measurement": "Model evaluation script", "responsible": "ML Lead", "verification": "Joint review with ML Lead"}, {"id": "AC-04", "description": "All HSCN integrations pass NHS Digital security review before production cutover.", "measurement": "Penetration test report", "responsible": "Compliance Lead", "verification": "NHS Digital security board sign-off"}, {"id": "AC-05", "description": "Compliance pack (DPIA + IG approval + DSPT) is filed and acknowledged by NHS Digital.", "measurement": "Filing receipt from DPO", "responsible": "Compliance Lead", "verification": "Email confirmation from NHS DPO office"}, {"id": "AC-06", "description": "Operations runbook reviewed and signed off by NHS Digital Service Operations Lead.", "measurement": "Signed sign-off form", "responsible": "Delivery Lead", "verification": "Joint review session minutes"}, {"id": "AC-07", "description": "Centific delivers training to two cohorts of NHS Trust users (\u226425 attendees each).", "measurement": "Attendance register", "responsible": "Delivery Lead", "verification": "Post-training feedback survey \u2265 80% positive"}, {"id": "AC-08", "description": "Knowledge transfer artefacts delivered and reviewed in a joint handover workshop.", "measurement": "Workshop attendance + KT pack", "responsible": "Solution Architect", "verification": "Trust IT signs off KT pack"}, {"id": "AC-09", "description": "Hypercare period of 30 calendar days post go-live with a defined SLA.", "measurement": "Hypercare ticket log", "responsible": "Delivery Lead", "verification": "Daily standups + SLA dashboard"}]}'::jsonb, NULL, 'acceptance_module', 'v1.2', 0.730, 0, '[]'::jsonb, NULL, NULL, NULL, '2026-04-25T08:12:40.522547+00:00'::timestamptz, '2026-04-25T14:55:05.016458+00:00'::timestamptz);
